//! Dynamic, mode-separated Tauri titlebar Island.
//!
//! The compact object opens focused-agent interaction. Session switching and
//! transcript recall are distinct surfaces with distinct entry points and
//! result semantics; they are never stacked into one dashboard.

use leptos::ev::{KeyboardEvent, SubmitEvent};
use leptos::prelude::*;
use wasm_bindgen::JsCast;

use crate::daemon::{Daemon, HistorySearchHit};
use crate::island::{
    compact_attention_counts, derive_attention_items, derive_island_sessions,
    permission_action_state, search_island, stop_action_state, IslandAttentionItem, IslandResult,
};
use crate::sessions::fmt_relative_time;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IslandMode {
    Closed,
    Agent,
    Sessions,
    Recall,
}

fn option_id(prefix: &str, value: &str) -> String {
    let encoded = value
        .as_bytes()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    format!("{prefix}-{encoded}")
}

fn next_index(index: usize, len: usize) -> usize {
    if len == 0 {
        0
    } else {
        (index + 1) % len
    }
}

fn previous_index(index: usize, len: usize) -> usize {
    if len == 0 {
        0
    } else {
        (index + len - 1) % len
    }
}

fn history_result_label(hit: &HistorySearchHit) -> String {
    let title = if hit.session_title.trim().is_empty() {
        "Untitled session"
    } else {
        hit.session_title.trim()
    };
    format!("Open history match from {title}")
}

#[component]
fn AgentStage(
    daemon: Daemon,
    items: Memo<Vec<IslandAttentionItem>>,
    selected_index: RwSignal<usize>,
    on_close: Callback<()>,
    on_mode: Callback<IslandMode>,
) -> impl IntoView {
    let prompt = RwSignal::new(String::new());
    let prompt_ref: NodeRef<leptos::html::Input> = NodeRef::new();
    let focused_id = daemon.session_id;
    let pending_permissions = daemon.pending_permissions;
    let active_decision_token = daemon.active_decision_token;
    let request_cancellations = daemon.request_cancellations;
    let session_title = daemon.session_title;
    let status = daemon.status;
    let daemon = StoredValue::new(daemon);

    Effect::new(move |_| {
        let len = items.get().len();
        if len == 0 {
            selected_index.set(0);
            request_animation_frame(move || {
                if let Some(input) = prompt_ref.get() {
                    let _ = input.focus();
                }
            });
        } else if selected_index.get() >= len {
            selected_index.set(0);
        }
    });

    let submit = move |event: SubmitEvent| {
        event.prevent_default();
        let text = prompt.get_untracked().trim().to_string();
        if text.is_empty() {
            return;
        }
        daemon.get_value().send_prompt(text);
        prompt.set(String::new());
        on_close.run(());
    };

    view! {
        <section class="island-agent" aria-label="Agent interaction">
            <header class="island-stage__header">
                <div class="island-stage__identity">
                    <span class="island-stage__eyebrow">"Agent"</span>
                    <strong>{move || {
                        let title = session_title.get();
                        if title.trim().is_empty() { "Ocean".to_string() } else { title }
                    }}</strong>
                </div>
                <div class="island-stage__routes" aria-label="Island tools">
                    <button type="button" on:click=move |_| on_mode.run(IslandMode::Sessions)>
                        "Sessions"
                    </button>
                    <button type="button" on:click=move |_| on_mode.run(IslandMode::Recall)>
                        "Recall"
                    </button>
                </div>
            </header>

            <Show when=move || items.get().is_empty()>
                <div class="island-agent__idle">
                    <span class="island-agent__pulse" aria-hidden="true"></span>
                    <div>
                        <strong>"Ocean is ready"</strong>
                        <p>{move || status.get()}</p>
                    </div>
                </div>
                <form class="island-agent__composer" on:submit=submit>
                    <input
                        node_ref=prompt_ref
                        type="text"
                        aria-label="Ask Ocean in the focused session"
                        placeholder="Ask Ocean…"
                        autocomplete="off"
                        prop:value=move || prompt.get()
                        on:input=move |event| prompt.set(event_target_value(&event))
                    />
                    <button type="submit" disabled=move || prompt.get().trim().is_empty()>
                        "Send"
                    </button>
                </form>
            </Show>

            <Show when=move || !items.get().is_empty()>
                <div class="island-agent__position">
                    <span>{move || {
                        let len = items.get().len();
                        format!("Work {} of {len}", selected_index.get().min(len.saturating_sub(1)) + 1)
                    }}</span>
                    <Show when=move || items.get().len().ge(&2)>
                        <div class="island-agent__stepper">
                            <button
                                type="button"
                                aria-label="Previous agent work item"
                                on:click=move |_| {
                                    let len = items.get_untracked().len();
                                    selected_index.update(|index| *index = previous_index(*index, len));
                                }
                            >"←"</button>
                            <button
                                type="button"
                                aria-label="Next agent work item"
                                on:click=move |_| {
                                    let len = items.get_untracked().len();
                                    selected_index.update(|index| *index = next_index(*index, len));
                                }
                            >"→"</button>
                        </div>
                    </Show>
                </div>

                <For
                    each=move || {
                        items
                            .get()
                            .get(selected_index.get())
                            .cloned()
                            .into_iter()
                            .collect::<Vec<_>>()
                    }
                    key=|item| (item.id.clone(), item.state, item.updated_at.clone())
                    children=move |item| {
                        let item_class = format!(
                            "island-agent__work {}",
                            item.state.class_name(),
                        );
                        let state_label = item.state.label();
                        let session_name = item.session_title.clone();
                        let detail = item.detail.clone();
                        let project = item.project.clone().unwrap_or_default();
                        let tool = item.tool.clone().unwrap_or_default();
                        let updated = if item.updated_at.is_empty() {
                            String::new()
                        } else {
                            fmt_relative_time(&item.updated_at)
                        };
                        let permission_id = StoredValue::new_local(item.permission_id.clone());
                        let permission_session = StoredValue::new_local(item.session_id.clone());
                        let open_target = StoredValue::new_local((
                            item.session_id.clone(),
                            item.session_title.clone(),
                        ));
                        let request_id = StoredValue::new_local(item.request_id.clone());
                        let item_state = item.state;
                        let permission_action = Memo::new(move |_| {
                            permission_action_state(
                                permission_id.get_value().as_deref(),
                                permission_session.get_value().as_deref(),
                                focused_id.get().as_deref(),
                                active_decision_token.get().is_some(),
                                &pending_permissions.get(),
                            )
                        });
                        let stop_action = Memo::new(move |_| {
                            stop_action_state(
                                item_state,
                                &request_id.get_value(),
                                &request_cancellations.get(),
                            )
                        });
                        let open_action = Memo::new(move |_| {
                            let (session_id, _) = open_target.get_value();
                            permission_action.get().is_none()
                                && session_id.is_some()
                                && session_id.as_deref() != focused_id.get().as_deref()
                        });

                        view! {
                            <article class=item_class>
                                <div class="island-agent__work-head">
                                    <span class="island-agent__state">
                                        <i aria-hidden="true"></i>
                                        {state_label}
                                    </span>
                                    <strong>{session_name}</strong>
                                </div>
                                <p class="island-agent__detail">{detail}</p>
                                <div class="island-agent__meta">
                                    <span>{project}</span>
                                    <span>{tool}</span>
                                    <span>{updated}</span>
                                </div>
                                <div class="island-agent__actions">
                                    <Show when=move || open_action.get()>
                                        <button
                                            class="island-agent__open"
                                            type="button"
                                            on:click=move |_| {
                                                let (session_id, title) = open_target.get_value();
                                                if let Some(session_id) = session_id {
                                                    daemon.get_value().switch_session(session_id, title);
                                                    on_close.run(());
                                                }
                                            }
                                        >"Open session"</button>
                                    </Show>
                                    <Show when=move || stop_action.get().is_some()>
                                        <button
                                            class="island-agent__stop"
                                            type="button"
                                            disabled=move || stop_action.get().unwrap_or(true)
                                            on:click=move |_| {
                                                daemon.get_value().cancel_request(request_id.get_value());
                                            }
                                        >
                                            {move || if stop_action.get() == Some(true) { "Stopping…" } else { "Stop" }}
                                        </button>
                                    </Show>
                                    <Show when=move || permission_action.get().is_some()>
                                        <button
                                            class="island-agent__deny"
                                            type="button"
                                            disabled=move || permission_action.get().unwrap_or(true)
                                            on:click=move |_| {
                                                if let Some(permission_id) = permission_id.get_value() {
                                                    daemon.get_value().decide_permission(permission_id, false);
                                                }
                                            }
                                        >"Deny"</button>
                                        <button
                                            class="island-agent__approve"
                                            type="button"
                                            disabled=move || permission_action.get().unwrap_or(true)
                                            on:click=move |_| {
                                                if let Some(permission_id) = permission_id.get_value() {
                                                    daemon.get_value().decide_permission(permission_id, true);
                                                }
                                            }
                                        >
                                            {move || if permission_action.get() == Some(true) { "Working…" } else { "Approve" }}
                                        </button>
                                    </Show>
                                </div>
                            </article>
                        }
                    }
                />
            </Show>
        </section>
    }
}

#[component]
pub fn DynamicIsland(
    daemon: Daemon,
    mode: RwSignal<IslandMode>,
    focus_request: RwSignal<u64>,
    on_open: Callback<IslandMode>,
) -> impl IntoView {
    let session_query = RwSignal::new(String::new());
    let history_query = RwSignal::new(String::new());
    let session_selected = RwSignal::new(0usize);
    let history_selected = RwSignal::new(0usize);
    let agent_selected = RwSignal::new(0usize);
    let history_debounce = RwSignal::new(0u64);
    let previous_mode = RwSignal::new(IslandMode::Closed);
    let previous_focus = StoredValue::new_local(None::<web_sys::HtmlElement>);
    let last_focus_request = RwSignal::new(0u64);
    let session_input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
    let history_input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
    let chip_ref: NodeRef<leptos::html::Button> = NodeRef::new();
    let stage_ref: NodeRef<leptos::html::Section> = NodeRef::new();

    #[cfg(target_arch = "wasm32")]
    let attention_interval = {
        let daemon = daemon.clone();
        send_wrapper::SendWrapper::new(gloo_timers::callback::Interval::new(3_000, move || {
            daemon.fetch_attention();
        }))
    };
    #[cfg(target_arch = "wasm32")]
    on_cleanup(move || drop(attention_interval));

    let session_list = daemon.session_list;
    let request_list = daemon.request_list;
    let permission_list = daemon.permission_list;
    let projects = daemon.projects;
    let focused_id = daemon.session_id;
    let history_results = daemon.history_results;
    let history_searching = daemon.history_searching;
    let history_error = daemon.history_error;
    let daemon_value = StoredValue::new(daemon.clone());

    daemon.fetch_sessions();
    daemon.fetch_projects();
    daemon.fetch_attention();

    let sessions = Memo::new(move |_| {
        derive_island_sessions(
            &session_list.get(),
            &projects.get(),
            focused_id.get().as_deref(),
        )
    });
    let attention_items = Memo::new(move |_| {
        derive_attention_items(&request_list.get(), &permission_list.get(), &sessions.get())
    });
    let attention_counts = Memo::new(move |_| compact_attention_counts(&attention_items.get()));
    let session_results = Memo::new(move |_| {
        let mut matches = search_island(&session_query.get(), &sessions.get());
        matches.truncate(if session_query.get().trim().is_empty() {
            8
        } else {
            20
        });
        matches
    });

    Effect::new(move |_| {
        let len = session_results.get().len();
        if len == 0 || session_selected.get() >= len {
            session_selected.set(0);
        }
    });
    Effect::new(move |_| {
        let len = history_results.get().len();
        if len == 0 || history_selected.get() >= len {
            history_selected.set(0);
        }
    });

    Effect::new(move |_| {
        let next = mode.get();
        let request = focus_request.get();
        let previous = previous_mode.get_untracked();
        let previous_request = last_focus_request.get_untracked();
        if next != IslandMode::Closed && previous == IslandMode::Closed {
            previous_focus.set_value(
                web_sys::window()
                    .and_then(|window| window.document())
                    .and_then(|document| document.active_element())
                    .and_then(|element| element.dyn_into::<web_sys::HtmlElement>().ok()),
            );
            let daemon = daemon_value.get_value();
            daemon.fetch_sessions();
            daemon.fetch_projects();
            daemon.fetch_attention();
        }
        let should_focus = next != IslandMode::Closed
            && (previous == IslandMode::Closed || next != previous || request != previous_request);
        if should_focus {
            request_animation_frame(move || match next {
                IslandMode::Sessions => {
                    if let Some(input) = session_input_ref.get() {
                        let _ = input.focus();
                        input.select();
                    }
                }
                IslandMode::Recall => {
                    if let Some(input) = history_input_ref.get() {
                        let _ = input.focus();
                        input.select();
                    }
                }
                IslandMode::Agent => {
                    if let Some(stage) = stage_ref.get() {
                        let _ = stage.focus();
                    }
                }
                IslandMode::Closed => {}
            });
        } else if next == IslandMode::Closed && previous != IslandMode::Closed {
            request_animation_frame(move || {
                if let Some(element) = previous_focus.get_value().filter(|el| el.is_connected()) {
                    let _ = element.focus();
                } else if let Some(chip) = chip_ref.get() {
                    let _ = chip.focus();
                }
            });
        }
        previous_mode.set(next);
        last_focus_request.set(request);
    });

    let close = Callback::new(move |()| mode.set(IslandMode::Closed));
    let switch_mode = Callback::new(move |next| on_open.run(next));
    let selected_session_id = move || {
        session_results
            .get()
            .get(session_selected.get())
            .map(|result| match result {
                IslandResult::Session(item) => option_id("island-session", &item.id),
            })
            .unwrap_or_default()
    };
    let selected_history_id = move || {
        history_results
            .get()
            .get(history_selected.get())
            .map(|hit| option_id("island-history", &hit.hit_id))
            .unwrap_or_default()
    };

    let on_keydown = move |event: KeyboardEvent| {
        if event.is_composing() || mode.get_untracked() == IslandMode::Closed {
            return;
        }
        if event.key() == "Escape" {
            event.prevent_default();
            event.stop_propagation();
            close.run(());
            return;
        }

        match mode.get_untracked() {
            IslandMode::Sessions => {
                let from_input = event
                    .target()
                    .and_then(|target| target.dyn_into::<web_sys::HtmlElement>().ok())
                    .is_some_and(|element| element.class_list().contains("island-search__input"));
                if !from_input {
                    return;
                }
                let len = session_results.get_untracked().len();
                match event.key().as_str() {
                    "ArrowDown" => {
                        event.prevent_default();
                        session_selected.update(|index| *index = next_index(*index, len));
                    }
                    "ArrowUp" => {
                        event.prevent_default();
                        session_selected.update(|index| *index = previous_index(*index, len));
                    }
                    "Enter" => {
                        event.prevent_default();
                        if let Some(IslandResult::Session(item)) = session_results
                            .get_untracked()
                            .get(session_selected.get_untracked())
                        {
                            daemon_value
                                .get_value()
                                .switch_session(item.id.clone(), item.title.clone());
                            close.run(());
                        }
                    }
                    _ => {}
                }
            }
            IslandMode::Recall => {
                let from_input = event
                    .target()
                    .and_then(|target| target.dyn_into::<web_sys::HtmlElement>().ok())
                    .is_some_and(|element| element.class_list().contains("island-recall__input"));
                if !from_input {
                    return;
                }
                let len = history_results.get_untracked().len();
                match event.key().as_str() {
                    "ArrowDown" => {
                        event.prevent_default();
                        history_selected.update(|index| *index = next_index(*index, len));
                    }
                    "ArrowUp" => {
                        event.prevent_default();
                        history_selected.update(|index| *index = previous_index(*index, len));
                    }
                    "Enter" => {
                        event.prevent_default();
                        if let Some(hit) = history_results
                            .get_untracked()
                            .get(history_selected.get_untracked())
                        {
                            daemon_value
                                .get_value()
                                .switch_session(hit.session_id.clone(), hit.session_title.clone());
                            close.run(());
                        }
                    }
                    _ => {}
                }
            }
            IslandMode::Agent => match event.key().as_str() {
                "ArrowLeft" => {
                    let len = attention_items.get_untracked().len();
                    if len > 1 {
                        event.prevent_default();
                        agent_selected.update(|index| *index = previous_index(*index, len));
                    }
                }
                "ArrowRight" => {
                    let len = attention_items.get_untracked().len();
                    if len > 1 {
                        event.prevent_default();
                        agent_selected.update(|index| *index = next_index(*index, len));
                    }
                }
                _ => {}
            },
            IslandMode::Closed => {}
        }
    };

    let focused_session = Memo::new(move |_| {
        sessions
            .get()
            .into_iter()
            .find(|session| session.is_focused)
    });
    let chip_status = move || {
        let (needs_human, running) = attention_counts.get();
        if needs_human == 1 {
            "1 needs you".to_string()
        } else if needs_human > 1 {
            format!("{needs_human} need you")
        } else if running > 0 {
            format!("{running} running")
        } else {
            "Ready".to_string()
        }
    };
    let chip_label = move || {
        focused_session.get().map_or_else(
            || format!("Ocean agent. {}. Open agent interaction", chip_status()),
            |session| {
                format!(
                    "Ocean agent in session {}. {}. Open agent interaction",
                    session.title,
                    chip_status(),
                )
            },
        )
    };
    let stage_label = move || match mode.get() {
        IslandMode::Agent => "Agent interaction",
        IslandMode::Sessions => "Switch session",
        IslandMode::Recall => "Recall transcript history",
        IslandMode::Closed => "Ocean Island",
    };

    view! {
        <section class="island-host island-host--dynamic" on:keydown=on_keydown>
            <button
                class=move || {
                    let (needs_human, running) = attention_counts.get();
                    if needs_human > 0 {
                        "island-chip is-attention"
                    } else if running > 0 {
                        "island-chip is-running"
                    } else {
                        "island-chip"
                    }
                }
                type="button"
                node_ref=chip_ref
                aria-label=chip_label
                aria-haspopup="dialog"
                aria-expanded=move || (mode.get() != IslandMode::Closed).to_string()
                aria-controls="island-stage"
                on:click=move |_| {
                    if mode.get_untracked() == IslandMode::Closed {
                        on_open.run(IslandMode::Agent);
                    } else {
                        close.run(());
                    }
                }
            >
                <span
                    class=move || {
                        let (needs_human, running) = attention_counts.get();
                        if needs_human > 0 {
                            "island-chip__dot is-attention"
                        } else if running > 0 {
                            "island-chip__dot is-running"
                        } else if focused_session.get().is_none() {
                            "island-chip__dot is-empty"
                        } else {
                            "island-chip__dot"
                        }
                    }
                    aria-hidden="true"
                ></span>
                <span class="island-chip__title">
                    {move || focused_session.get().map(|item| item.title).unwrap_or_else(|| "Ocean".into())}
                </span>
                <Show when=move || focused_session.get().and_then(|item| item.project).is_some()>
                    <span class="island-chip__separator" aria-hidden="true">"·"</span>
                    <span class="island-chip__project">
                        {move || focused_session.get().and_then(|item| item.project).unwrap_or_default()}
                    </span>
                </Show>
                <span class="island-chip__separator" aria-hidden="true">"·"</span>
                <span class="island-chip__count">{move || chip_status()}</span>
            </button>
            <span class="island-live" aria-live="polite" aria-atomic="true">
                {move || chip_status()}
            </span>

            <Show when=move || mode.get() != IslandMode::Closed>
                <div class="island-dismiss-layer" aria-hidden="true" on:click=move |_| close.run(())></div>
                <section
                    id="island-stage"
                    class=move || format!(
                        "island-stage island-stage--{}",
                        match mode.get() {
                            IslandMode::Agent => "agent",
                            IslandMode::Sessions => "sessions",
                            IslandMode::Recall => "recall",
                            IslandMode::Closed => "closed",
                        }
                    )
                    node_ref=stage_ref
                    tabindex="-1"
                    role="dialog"
                    aria-modal="false"
                    aria-label=stage_label
                >
                    <Show when=move || mode.get() == IslandMode::Agent>
                        <AgentStage
                            daemon=daemon_value.get_value()
                            items=attention_items
                            selected_index=agent_selected
                            on_close=close
                            on_mode=switch_mode
                        />
                    </Show>

                    <Show when=move || mode.get() == IslandMode::Sessions>
                        <section class="island-sessions" aria-label="Sessions">
                            <header class="island-stage__header">
                                <div class="island-stage__identity">
                                    <span class="island-stage__eyebrow">"Sessions"</span>
                                    <strong>"Switch focus"</strong>
                                </div>
                                <span class="island-stage__hint">"⌘P"</span>
                            </header>
                            <div class="island-search">
                                <input
                                    class="island-search__input"
                                    type="search"
                                    role="combobox"
                                    aria-label="Search sessions"
                                    aria-autocomplete="list"
                                    aria-expanded="true"
                                    aria-controls="island-session-results"
                                    aria-activedescendant=move || {
                                        let id = selected_session_id();
                                        (!id.is_empty()).then_some(id)
                                    }
                                    placeholder="Session, project, path, branch…"
                                    autocomplete="off"
                                    node_ref=session_input_ref
                                    prop:value=move || session_query.get()
                                    on:input=move |event| {
                                        session_query.set(event_target_value(&event));
                                        session_selected.set(0);
                                    }
                                />
                            </div>
                            <div id="island-session-results" class="island-results" role="listbox">
                                <Show
                                    when=move || !session_results.get().is_empty()
                                    fallback=|| view! { <div class="island-empty">"No matching sessions"</div> }
                                >
                                    <For
                                        each=move || session_results.get()
                                        key=|result| match result { IslandResult::Session(item) => item.id.clone() }
                                        children=move |result| {
                                            let IslandResult::Session(item) = result;
                                            let row_id = option_id("island-session", &item.id);
                                            let selected_id = row_id.clone();
                                            let aria_id = row_id.clone();
                                            let switch_id = item.id.clone();
                                            let switch_title = item.title.clone();
                                            let title = item.title.clone();
                                            let project = item.project.clone().unwrap_or_default();
                                            let cwd = item.cwd.clone();
                                            let branch = item.branch.clone().unwrap_or_default();
                                            let updated = fmt_relative_time(&item.updated_at);
                                            let is_focused = item.is_focused;
                                            view! {
                                                <button
                                                    id=row_id
                                                    class="island-result"
                                                    class:island-result--selected=move || selected_session_id() == selected_id
                                                    class:island-result--focused=is_focused
                                                    type="button"
                                                    role="option"
                                                    tabindex="-1"
                                                    aria-selected=move || (selected_session_id() == aria_id).to_string()
                                                    on:click=move |_| {
                                                        daemon_value.get_value().switch_session(
                                                            switch_id.clone(),
                                                            switch_title.clone(),
                                                        );
                                                        close.run(());
                                                    }
                                                >
                                                    <span class="island-result__primary">
                                                        <span class="island-result__title">{title}</span>
                                                        <Show when=move || is_focused>
                                                            <span class="island-result__focused">"Focused"</span>
                                                        </Show>
                                                    </span>
                                                    <span class="island-result__meta">
                                                        <span>{project}</span>
                                                        <span class="island-result__path">{cwd}</span>
                                                        <span>{branch}</span>
                                                        <span>{updated}</span>
                                                        <span>{format!("{} turns", item.turn_count)}</span>
                                                    </span>
                                                </button>
                                            }
                                        }
                                    />
                                </Show>
                            </div>
                        </section>
                    </Show>

                    <Show when=move || mode.get() == IslandMode::Recall>
                        <section class="island-recall" aria-label="Recall history">
                            <header class="island-stage__header">
                                <div class="island-stage__identity">
                                    <span class="island-stage__eyebrow">"Recall"</span>
                                    <strong>"Search transcript history"</strong>
                                </div>
                                <span class="island-stage__hint">"⌘⇧F"</span>
                            </header>
                            <div class="island-recall__search">
                                <input
                                    class="island-recall__input"
                                    type="search"
                                    role="combobox"
                                    aria-label="Search transcript history"
                                    aria-autocomplete="list"
                                    aria-expanded="true"
                                    aria-controls="island-history-results"
                                    aria-activedescendant=move || {
                                        let id = selected_history_id();
                                        (!id.is_empty()).then_some(id)
                                    }
                                    placeholder="What did we discuss, decide, or change?"
                                    autocomplete="off"
                                    node_ref=history_input_ref
                                    prop:value=move || history_query.get()
                                    on:input=move |event| {
                                        let query = event_target_value(&event);
                                        history_query.set(query.clone());
                                        history_selected.set(0);
                                        let generation = history_debounce.get_untracked().wrapping_add(1);
                                        history_debounce.set(generation);
                                        let daemon = daemon_value.get_value();
                                        wasm_bindgen_futures::spawn_local(async move {
                                            #[cfg(target_arch = "wasm32")]
                                            gloo_timers::future::TimeoutFuture::new(220).await;
                                            if history_debounce.get_untracked() == generation {
                                                daemon.search_history(query);
                                            }
                                        });
                                    }
                                />
                            </div>
                            <div id="island-history-results" class="island-recall__results" role="listbox">
                                <Show when=move || history_query.get().trim().is_empty()>
                                    <div class="island-recall__prompt">
                                        "Search the words inside prior user and assistant turns—not just session titles."
                                    </div>
                                </Show>
                                <Show when=move || history_searching.get()>
                                    <div class="island-recall__prompt">"Searching history…"</div>
                                </Show>
                                <Show when=move || history_error.get().is_some()>
                                    <div class="island-recall__error">
                                        {move || history_error.get().unwrap_or_default()}
                                    </div>
                                </Show>
                                <Show when=move || {
                                    !history_query.get().trim().is_empty()
                                        && !history_searching.get()
                                        && history_error.get().is_none()
                                        && history_results.get().is_empty()
                                }>
                                    <div class="island-recall__prompt">"No transcript matches"</div>
                                </Show>
                                <For
                                    each=move || history_results.get()
                                    key=|hit| hit.hit_id.clone()
                                    children=move |hit| {
                                        let row_id = option_id("island-history", &hit.hit_id);
                                        let selected_id = row_id.clone();
                                        let aria_id = row_id.clone();
                                        let session_id = hit.session_id.clone();
                                        let session_title = hit.session_title.clone();
                                        let title = if hit.session_title.trim().is_empty() {
                                            "Untitled session".to_string()
                                        } else {
                                            hit.session_title.clone()
                                        };
                                        let role = hit.role.clone();
                                        let excerpt = hit.excerpt.clone();
                                        let workspace = hit.workspace_root.clone().unwrap_or_default();
                                        let match_kind = hit.match_kind.clone();
                                        let label = history_result_label(&hit);
                                        view! {
                                            <button
                                                id=row_id
                                                class="island-recall__result"
                                                class:island-recall__result--selected=move || selected_history_id() == selected_id
                                                type="button"
                                                role="option"
                                                tabindex="-1"
                                                aria-label=label
                                                aria-selected=move || (selected_history_id() == aria_id).to_string()
                                                on:click=move |_| {
                                                    daemon_value.get_value().switch_session(
                                                        session_id.clone(),
                                                        session_title.clone(),
                                                    );
                                                    close.run(());
                                                }
                                            >
                                                <span class="island-recall__excerpt">{excerpt}</span>
                                                <span class="island-recall__meta">
                                                    <span>{title}</span>
                                                    <span>{role}</span>
                                                    <span>{workspace}</span>
                                                    <span>{match_kind}</span>
                                                </span>
                                            </button>
                                        }
                                    }
                                />
                            </div>
                        </section>
                    </Show>
                </section>
            </Show>
        </section>
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn modes_are_distinct_interactions() {
        assert_ne!(IslandMode::Agent, IslandMode::Sessions);
        assert_ne!(IslandMode::Sessions, IslandMode::Recall);
        assert_ne!(IslandMode::Agent, IslandMode::Recall);
    }

    #[test]
    fn bounded_session_results_keep_browse_small() {
        let items = (0..30)
            .map(|index| crate::island::IslandSession {
                id: format!("session-{index}"),
                title: format!("Session {index}"),
                project: None,
                cwd: "/tmp".into(),
                branch: None,
                origin: None,
                updated_at: format!("2026-07-15T00:{index:02}:00Z"),
                turn_count: 1,
                is_focused: index == 0,
                priority: if index == 0 {
                    crate::island::IslandPriority::Focused
                } else {
                    crate::island::IslandPriority::Background
                },
            })
            .collect::<Vec<_>>();
        let mut results = search_island("", &items);
        results.truncate(8);
        assert_eq!(results.len(), 8);
    }

    #[test]
    fn index_navigation_wraps() {
        assert_eq!(next_index(2, 3), 0);
        assert_eq!(previous_index(0, 3), 2);
        assert_eq!(next_index(0, 0), 0);
    }
}

text:
/* Dynamic Island — native agent interaction, Sessions, and Recall. Tauri-only
   in the component tree; these selectors remain inert on web/extension hosts. */

:root {
  --island-max-w: 520px;
  --island-top: 64px;
}

.ocean-header {
  position: relative;
}

.ocean-header__left {
  display: flex;
  align-items: center;
  min-width: 0;
}

/* Center inside the real header/content column without transform. Fixed
   descendants therefore stay viewport-fixed instead of inheriting a new
   containing block. The percentage cap reserves both titlebar control zones. */
.island-host {
  position: absolute;
  inset-inline: 0;
  top: 11px;
  width: min(var(--island-max-w), 44%);
  height: var(--ctl-h);
  margin-inline: auto;
  z-index: 122;
}

.island-chip {
  box-sizing: border-box;
  position: relative;
  z-index: 122;
  display: flex;
  align-items: center;
  gap: 7px;
  width: 100%;
  max-width: 100%;
  height: var(--ctl-h);
  min-width: 0;
  padding: 0 12px;
  border: 0;
  border-radius: var(--radius);
  background: var(--bg-elevated);
  box-shadow: var(--elev-1);
  color: var(--fg);
  font: 500 12px/1 var(--font);
  cursor: pointer;
  overflow: hidden;
  transition: background var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
}

.island-chip:hover,
.island-chip[aria-expanded="true"] {
  background: var(--bg-hover);
}

.island-chip:focus-visible {
  box-shadow: var(--elev-1), var(--focus-ring);
}

.island-chip__dot {
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  border-radius: var(--radius-pill);
  background: var(--fg-3);
}

.island-chip__dot.is-empty {
  background: var(--fg-4);
}

.island-chip.is-attention .island-chip__count {
  color: var(--warn);
}

.island-chip__dot.is-attention {
  background: var(--warn);
}

.island-chip.is-running .island-chip__count {
  color: var(--accent);
}

.island-chip__dot.is-running {
  background: var(--accent);
}

.island-live {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

.island-chip__title,
.island-chip__project,
.island-chip__count {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.island-chip__title {
  flex: 1 1 auto;
  text-align: left;
}

.island-chip__project {
  flex: 0 1 auto;
  color: var(--fg-2);
}

.island-chip__count,
.island-chip__separator {
  flex: 0 0 auto;
  color: var(--fg-2);
}

.island-search {
  flex: 0 0 auto;
  border-radius: var(--radius);
  background: var(--bg-elevated);
  box-shadow: var(--well);
}

.island-search__input {
  appearance: none;
  display: block;
  width: 100%;
  min-height: 40px;
  padding: 10px 12px;
  border: 0;
  border-radius: var(--radius);
  outline: 0;
  background: transparent;
  color: var(--fg);
  caret-color: var(--accent);
  font: 400 13px/1.4 var(--font);
}

.island-search__input::placeholder {
  color: var(--fg-3);
}

.island-search__input:focus-visible {
  box-shadow: var(--focus-ring);
}

.island-results {
  min-height: 0;
  max-height: min(464px, calc(100vh - var(--island-top) - 72px));
  overflow-y: auto;
  padding: 4px 0 0;
  border-radius: var(--radius);
}

.island-group {
  display: flex;
  flex-direction: column;
}

.island-result {
  appearance: none;
  width: 100%;
  min-width: 0;
  padding: 10px 12px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--fg-2);
  text-align: left;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease);
}

.island-result:hover,
.island-result--selected {
  background: var(--bg-hover);
}

.island-result:focus-visible {
  box-shadow: var(--focus-ring);
}

.island-result__primary,
.island-result__meta {
  display: flex;
  align-items: center;
  min-width: 0;
}

.island-result__primary {
  gap: 8px;
}

.island-result__title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg);
  font: 500 13px/1.35 var(--font);
}

.island-result__focused {
  flex: 0 0 auto;
  padding: 2px 5px;
  border-radius: var(--radius-sm);
  background: var(--accent-soft);
  color: var(--accent-bright);
  font: 600 9px/1.3 var(--font);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.island-result__meta {
  gap: 0;
  margin-top: 3px;
  color: var(--fg-3);
  font: 400 10px/1.4 var(--font);
  white-space: nowrap;
  overflow: hidden;
}

.island-result__meta > span {
  min-width: 0;
  max-width: 18ch;
  overflow: hidden;
  text-overflow: ellipsis;
}

.island-result__meta > span:empty {
  display: none;
}

.island-result__meta > span:not(:empty) ~ span:not(:empty)::before {
  content: "·";
  padding: 0 5px;
  color: var(--fg-4);
}

.island-result__path {
  font-family: var(--mono);
}

.island-empty {
  padding: 28px 16px;
  color: var(--fg-3);
  font: 400 12px/1.4 var(--font);
  text-align: center;
}

/* The workspace becomes a split column at 900px and may consume up to 65%
   of the window. Keep the remaining header to the identity dot/state dots so
   the centered Island has stable reserved tracks even at that maximum. */
@media (min-width: 900px) {
  .has-workspace-open .ocean-brand__word,
  .has-workspace-open .ocean-tokens,
  .has-workspace-open .ocean-status__text,
  .has-workspace-open .ocean-browser-control__label {
    display: none;
  }
}

@media (min-width: 900px) and (max-width: 1100px) {
  .has-workspace-open .ocean-brand {
    display: none;
  }
}

@media (max-width: 1000px) {
  .island-host {
    width: min(300px, 42%);
  }

  .island-chip__project,
  .island-chip__separator {
    display: none;
  }
}

/* Below the split-view breakpoint the workspace overlays from the right.
   Center the chip in the still-visible transcript column so workspace tabs
   never paint through the titlebar control. The popover remains viewport-wide
   and above the workspace, preserving the compact overlay behavior. */
@media (max-width: 899px) {
  .has-workspace-open .island-host {
    right: var(--workspace-w);
    /* The workspace resizer may intentionally leave only a 48px context
       sliver. Collapse rather than painting through traffic lights or tabs
       when that sliver cannot safely hold the interactive titlebar control. */
    max-width: max(0px, calc(100vw - var(--workspace-w) - 160px));
  }
}

@media (min-width: 721px) and (max-width: 840px) {
  .has-workspace-open .island-host {
    max-width: max(0px, calc(100vw - var(--workspace-w) - 220px));
  }
}

@media (min-width: 841px) and (max-width: 899px) {
  .has-workspace-open .island-host {
    max-width: max(0px, calc(100vw - var(--workspace-w) - 300px));
  }
}

@media (max-width: 840px) {
  .is-titlebar .ocean-brand__word {
    display: none;
  }

  .island-host {
    width: min(240px, 38%);
  }

  .island-chip {
    padding-inline: 9px;
  }

}

@media (max-width: 720px) {
  /* compact.css is later in the cascade; this higher-specificity titlebar
     rule keeps the native traffic-light inset at the supported minimum. */
  main.ocean-surface.is-titlebar .ocean-header {
    padding-left: var(--titlebar-inset);
  }

  .island-host {
    width: min(210px, 36%);
  }

  .has-workspace-open .ocean-brand {
    display: none;
  }

}

/* Dynamic Island v2 — one titlebar object, three mutually exclusive tools.
   The fixed outer stage begins behind the compact capsule so opening reads as
   the object changing shape, not a button spawning a detached modal. */
.island-dismiss-layer {
  position: fixed;
  inset: 0;
  z-index: 120;
  background: transparent;
}

.island-stage {
  --island-stage-radius: 22px;
  --island-stage-pad: 6px;
  position: fixed;
  top: 8px;
  left: 16px;
  right: 16px;
  z-index: 121;
  box-sizing: border-box;
  width: min(520px, calc(100vw - 32px));
  max-height: min(520px, calc(100vh - 24px));
  margin-inline: auto;
  padding: 48px var(--island-stage-pad) var(--island-stage-pad);
  border: 1px solid var(--border-subtle);
  border-radius: var(--island-stage-radius);
  outline: none;
  background: var(--sheen), var(--bg-raised);
  box-shadow: var(--elev-3);
  overflow: hidden;
  transform-origin: top center;
  animation: island-stage-open var(--dur-fast) var(--ease);
}

.island-stage--agent {
  width: min(460px, calc(100vw - 32px));
  max-height: min(330px, calc(100vh - 24px));
}

.island-stage--sessions {
  width: min(560px, calc(100vw - 32px));
}

.island-stage--recall {
  width: min(620px, calc(100vw - 32px));
}

.island-stage:focus-visible {
  box-shadow: var(--elev-3), var(--focus-ring);
}

.island-stage > section {
  border-radius: calc(var(--island-stage-radius) - var(--island-stage-pad));
}

@keyframes island-stage-open {
  from {
    opacity: 0;
    transform: scale(0.94, 0.72);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.island-stage__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 42px;
  padding: 7px 10px 9px;
}

.island-stage__identity {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.island-stage__identity strong {
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font: 600 13px/1.25 var(--font);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.island-stage__eyebrow,
.island-stage__hint,
.island-agent__position {
  color: var(--fg-3);
  font: 600 9px/1.2 var(--font);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.island-stage__routes {
  display: flex;
  align-items: center;
  gap: 2px;
}

.island-stage__routes button,
.island-agent__stepper button {
  appearance: none;
  min-height: var(--ctl-h-sm);
  padding: 0 8px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-3);
  font: 500 10px/1 var(--font);
  cursor: pointer;
}

.island-stage__routes button:hover,
.island-agent__stepper button:hover {
  background: var(--bg-hover);
  color: var(--fg);
}

.island-stage__routes button:focus-visible,
.island-agent__stepper button:focus-visible,
.island-agent__composer input:focus-visible,
.island-agent__composer button:focus-visible,
.island-agent__actions button:focus-visible,
.island-recall__input:focus-visible,
.island-recall__result:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.island-agent,
.island-sessions,
.island-recall {
  min-height: 0;
  background: var(--bg-raised);
  overflow: hidden;
}

.island-agent__idle {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 2px 4px 6px;
  padding: 12px;
  border-radius: calc(var(--island-stage-radius) - var(--island-stage-pad) - 4px);
  background: var(--bg-elevated);
}

.island-agent__pulse {
  width: 9px;
  height: 9px;
  flex: 0 0 9px;
  border-radius: var(--radius-pill);
  background: var(--ok);
  box-shadow: 0 0 0 5px var(--ok-soft);
}

.island-agent__idle strong,
.island-agent__idle p {
  display: block;
  margin: 0;
}

.island-agent__idle strong {
  color: var(--fg);
  font: 600 12px/1.4 var(--font);
}

.island-agent__idle p {
  margin-top: 2px;
  color: var(--fg-3);
  font: 400 10px/1.35 var(--font);
}

.island-agent__composer {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 6px;
  padding: 4px;
  border-radius: calc(var(--island-stage-radius) - var(--island-stage-pad));
  background: var(--bg-elevated);
  box-shadow: var(--well);
}

.island-agent__composer input {
  min-width: 0;
  min-height: 36px;
  padding: 0 10px;
  border: 0;
  border-radius: calc(var(--island-stage-radius) - var(--island-stage-pad) - 4px);
  outline: none;
  background: transparent;
  color: var(--fg);
  font: 400 12px/1.4 var(--font);
}

.island-agent__composer button,
.island-agent__actions button {
  appearance: none;
  min-height: var(--ctl-h-sm);
  padding: 0 10px;
  border: 0;
  border-radius: var(--radius);
  font: 600 10px/1 var(--font);
  cursor: pointer;
}

.island-agent__composer button,
.island-agent__approve {
  background: var(--accent);
  color: var(--fg-on-accent);
}

.island-agent__composer button:disabled,
.island-agent__actions button:disabled {
  opacity: 0.45;
  pointer-events: none;
}

.island-agent__position {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 28px;
  padding: 0 10px;
}

.island-agent__stepper {
  display: flex;
  align-items: center;
  gap: 2px;
}

.island-agent__work {
  margin: 0 4px 4px;
  padding: 12px;
  border-radius: calc(var(--island-stage-radius) - var(--island-stage-pad) - 4px);
  background: var(--bg-elevated);
}

.island-agent__work-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.island-agent__work-head strong {
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font: 600 12px/1.3 var(--font);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.island-agent__state {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--fg-3);
  font: 600 10px/1.3 var(--font);
}

.island-agent__state i {
  width: 7px;
  height: 7px;
  border-radius: var(--radius-pill);
  background: currentColor;
}

.island-agent__work.is-needs-human .island-agent__state,
.island-agent__work.is-cancelling .island-agent__state {
  color: var(--warn);
}

.island-agent__work.is-running .island-agent__state {
  color: var(--accent);
}

.island-agent__work.is-failed .island-agent__state {
  color: var(--err);
}

.island-agent__detail {
  margin: 10px 0 7px;
  color: var(--fg-2);
  font: 400 12px/1.5 var(--font);
  overflow-wrap: anywhere;
}

.island-agent__meta,
.island-recall__meta {
  display: flex;
  min-width: 0;
  overflow: hidden;
  color: var(--fg-3);
  font: 400 9px/1.4 var(--font);
  white-space: nowrap;
}

.island-agent__meta > span,
.island-recall__meta > span {
  min-width: 0;
  max-width: 24ch;
  overflow: hidden;
  text-overflow: ellipsis;
}

.island-agent__meta > span:empty,
.island-recall__meta > span:empty {
  display: none;
}

.island-agent__meta > span:not(:empty) ~ span:not(:empty)::before,
.island-recall__meta > span:not(:empty) ~ span:not(:empty)::before {
  content: "·";
  padding: 0 5px;
  color: var(--fg-4);
}

.island-agent__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  margin-top: 10px;
}

.island-agent__open {
  margin-right: auto;
  background: transparent;
  color: var(--fg-2);
}

.island-agent__open:hover {
  background: var(--bg-hover);
  color: var(--fg);
}

.island-agent__stop,
.island-agent__deny {
  background: transparent;
  color: var(--err);
}

.island-agent__stop:hover,
.island-agent__deny:hover {
  background: var(--err-soft);
}

.island-sessions .island-search,
.island-recall__search {
  margin: 0 4px 4px;
}

.island-sessions .island-results {
  max-height: min(370px, calc(100vh - 132px));
}

.island-recall__search {
  border-radius: var(--radius);
  background: var(--bg-elevated);
  box-shadow: var(--well);
}

.island-recall__input {
  appearance: none;
  display: block;
  width: 100%;
  min-height: 42px;
  padding: 10px 12px;
  border: 0;
  border-radius: var(--radius);
  outline: 0;
  background: transparent;
  color: var(--fg);
  caret-color: var(--accent);
  font: 400 13px/1.4 var(--font);
}

.island-recall__results {
  max-height: min(360px, calc(100vh - 132px));
  overflow-y: auto;
  padding: 2px 4px 4px;
}

.island-recall__prompt,
.island-recall__error {
  padding: 28px 14px;
  color: var(--fg-3);
  font: 400 11px/1.5 var(--font);
  text-align: center;
}

.island-recall__error {
  color: var(--err);
}

.island-recall__result {
  appearance: none;
  display: block;
  width: 100%;
  padding: 10px 12px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--fg-2);
  text-align: left;
  cursor: pointer;
}

.island-recall__result:hover,
.island-recall__result--selected {
  background: var(--bg-hover);
}

.island-recall__excerpt {
  display: -webkit-box;
  overflow: hidden;
  color: var(--fg);
  font: 500 12px/1.45 var(--font);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.island-recall__meta {
  margin-top: 5px;
}

@media (min-width: 900px) {
  .has-workspace-open .island-stage {
    right: calc(var(--workspace-w) + 16px);
    width: min(520px, calc(100vw - var(--workspace-w) - 32px));
  }

  .has-workspace-open .island-stage--agent {
    width: min(460px, calc(100vw - var(--workspace-w) - 32px));
  }

  .has-workspace-open .island-stage--recall {
    width: min(620px, calc(100vw - var(--workspace-w) - 32px));
  }
}

@media (max-width: 720px) {
  .island-stage {
    left: 10px;
    right: 10px;
    width: calc(100vw - 20px);
    max-height: min(520px, calc(100vh - 18px));
  }

  .island-stage__header {
    padding-inline: 8px;
  }

  .island-stage__routes {
    gap: 0;
  }

  .island-stage__routes button {
    padding-inline: 6px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .island-chip,
  .island-result,
  .island-stage {
    animation: none;
    transition: none;
  }
}

content.text:
/* Dynamic Island — native agent interaction, Sessions, and Recall. Tauri-only
   in the component tree; these selectors remain inert on web/extension hosts. */

:root {
  --island-max-w: 520px;
  --island-top: 64px;
}

.ocean-header {
  position: relative;
}

.ocean-header__left {
  display: flex;
  align-items: center;
  min-width: 0;
}

/* Center inside the real header/content column without transform. Fixed
   descendants therefore stay viewport-fixed instead of inheriting a new
   containing block. The percentage cap reserves both titlebar control zones. */
.island-host {
  position: absolute;
  inset-inline: 0;
  top: 11px;
  width: min(var(--island-max-w), 44%);
  height: var(--ctl-h);
  margin-inline: auto;
  z-index: 122;
}

.island-chip {
  box-sizing: border-box;
  position: relative;
  z-index: 122;
  display: flex;
  align-items: center;
  gap: 7px;
  width: 100%;
  max-width: 100%;
  height: var(--ctl-h);
  min-width: 0;
  padding: 0 12px;
  border: 0;
  border-radius: var(--radius);
  background: var(--bg-elevated);
  box-shadow: var(--elev-1);
  color: var(--fg);
  font: 500 12px/1 var(--font);
  cursor: pointer;
  overflow: hidden;
  transition: background var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
}

.island-chip:hover,
.island-chip[aria-expanded="true"] {
  background: var(--bg-hover);
}

.island-chip:focus-visible {
  box-shadow: var(--elev-1), var(--focus-ring);
}

.island-chip__dot {
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  border-radius: var(--radius-pill);
  background: var(--fg-3);
}

.island-chip__dot.is-empty {
  background: var(--fg-4);
}

.island-chip.is-attention .island-chip__count {
  color: var(--warn);
}

.island-chip__dot.is-attention {
  background: var(--warn);
}

.island-chip.is-running .island-chip__count {
  color: var(--accent);
}

.island-chip__dot.is-running {
  background: var(--accent);
}

.island-live {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

.island-chip__title,
.island-chip__project,
.island-chip__count {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.island-chip__title {
  flex: 1 1 auto;
  text-align: left;
}

.island-chip__project {
  flex: 0 1 auto;
  color: var(--fg-2);
}

.island-chip__count,
.island-chip__separator {
  flex: 0 0 auto;
  color: var(--fg-2);
}

.island-search {
  flex: 0 0 auto;
  border-radius: var(--radius);
  background: var(--bg-elevated);
  box-shadow: var(--well);
}

.island-search__input {
  appearance: none;
  display: block;
  width: 100%;
  min-height: 40px;
  padding: 10px 12px;
  border: 0;
  border-radius: var(--radius);
  outline: 0;
  background: transparent;
  color: var(--fg);
  caret-color: var(--accent);
  font: 400 13px/1.4 var(--font);
}

.island-search__input::placeholder {
  color: var(--fg-3);
}

.island-search__input:focus-visible {
  box-shadow: var(--focus-ring);
}

.island-results {
  min-height: 0;
  max-height: min(464px, calc(100vh - var(--island-top) - 72px));
  overflow-y: auto;
  padding: 4px 0 0;
  border-radius: var(--radius);
}

.island-group {
  display: flex;
  flex-direction: column;
}

.island-result {
  appearance: none;
  width: 100%;
  min-width: 0;
  padding: 10px 12px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--fg-2);
  text-align: left;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease);
}

.island-result:hover,
.island-result--selected {
  background: var(--bg-hover);
}

.island-result:focus-visible {
  box-shadow: var(--focus-ring);
}

.island-result__primary,
.island-result__meta {
  display: flex;
  align-items: center;
  min-width: 0;
}

.island-result__primary {
  gap: 8px;
}

.island-result__title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg);
  font: 500 13px/1.35 var(--font);
}

.island-result__focused {
  flex: 0 0 auto;
  padding: 2px 5px;
  border-radius: var(--radius-sm);
  background: var(--accent-soft);
  color: var(--accent-bright);
  font: 600 9px/1.3 var(--font);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.island-result__meta {
  gap: 0;
  margin-top: 3px;
  color: var(--fg-3);
  font: 400 10px/1.4 var(--font);
  white-space: nowrap;
  overflow: hidden;
}

.island-result__meta > span {
  min-width: 0;
  max-width: 18ch;
  overflow: hidden;
  text-overflow: ellipsis;
}

.island-result__meta > span:empty {
  display: none;
}

.island-result__meta > span:not(:empty) ~ span:not(:empty)::before {
  content: "·";
  padding: 0 5px;
  color: var(--fg-4);
}

.island-result__path {
  font-family: var(--mono);
}

.island-empty {
  padding: 28px 16px;
  color: var(--fg-3);
  font: 400 12px/1.4 var(--font);
  text-align: center;
}

/* The workspace becomes a split column at 900px and may consume up to 65%
   of the window. Keep the remaining header to the identity dot/state dots so
   the centered Island has stable reserved tracks even at that maximum. */
@media (min-width: 900px) {
  .has-workspace-open .ocean-brand__word,
  .has-workspace-open .ocean-tokens,
  .has-workspace-open .ocean-status__text,
  .has-workspace-open .ocean-browser-control__label {
    display: none;
  }
}

@media (min-width: 900px) and (max-width: 1100px) {
  .has-workspace-open .ocean-brand {
    display: none;
  }
}

@media (max-width: 1000px) {
  .island-host {
    width: min(300px, 42%);
  }

  .island-chip__project,
  .island-chip__separator {
    display: none;
  }
}

/* Below the split-view breakpoint the workspace overlays from the right.
   Center the chip in the still-visible transcript column so workspace tabs
   never paint through the titlebar control. The popover remains viewport-wide
   and above the workspace, preserving the compact overlay behavior. */
@media (max-width: 899px) {
  .has-workspace-open .island-host {
    right: var(--workspace-w);
    /* The workspace resizer may intentionally leave only a 48px context
       sliver. Collapse rather than painting through traffic lights or tabs
       when that sliver cannot safely hold the interactive titlebar control. */
    max-width: max(0px, calc(100vw - var(--workspace-w) - 160px));
  }
}

@media (min-width: 721px) and (max-width: 840px) {
  .has-workspace-open .island-host {
    max-width: max(0px, calc(100vw - var(--workspace-w) - 220px));
  }
}

@media (min-width: 841px) and (max-width: 899px) {
  .has-workspace-open .island-host {
    max-width: max(0px, calc(100vw - var(--workspace-w) - 300px));
  }
}

@media (max-width: 840px) {
  .is-titlebar .ocean-brand__word {
    display: none;
  }

  .island-host {
    width: min(240px, 38%);
  }

  .island-chip {
    padding-inline: 9px;
  }

}

@media (max-width: 720px) {
  /* compact.css is later in the cascade; this higher-specificity titlebar
     rule keeps the native traffic-light inset at the supported minimum. */
  main.ocean-surface.is-titlebar .ocean-header {
    padding-left: var(--titlebar-inset);
  }

  .island-host {
    width: min(210px, 36%);
  }

  .has-workspace-open .ocean-brand {
    display: none;
  }

}

/* Dynamic Island v2 — one titlebar object, three mutually exclusive tools.
   The fixed outer stage begins behind the compact capsule so opening reads as
   the object changing shape, not a button spawning a detached modal. */
.island-dismiss-layer {
  position: fixed;
  inset: 0;
  z-index: 120;
  background: transparent;
}

.island-stage {
  --island-stage-radius: 22px;
  --island-stage-pad: 6px;
  position: fixed;
  top: 8px;
  left: 16px;
  right: 16px;
  z-index: 121;
  box-sizing: border-box;
  width: min(520px, calc(100vw - 32px));
  max-height: min(520px, calc(100vh - 24px));
  margin-inline: auto;
  padding: 48px var(--island-stage-pad) var(--island-stage-pad);
  border: 1px solid var(--border-subtle);
  border-radius: var(--island-stage-radius);
  outline: none;
  background: var(--sheen), var(--bg-raised);
  box-shadow: var(--elev-3);
  overflow: hidden;
  transform-origin: top center;
  animation: island-stage-open var(--dur-fast) var(--ease);
}

.island-stage--agent {
  width: min(460px, calc(100vw - 32px));
  max-height: min(330px, calc(100vh - 24px));
}

.island-stage--sessions {
  width: min(560px, calc(100vw - 32px));
}

.island-stage--recall {
  width: min(620px, calc(100vw - 32px));
}

.island-stage:focus-visible {
  box-shadow: var(--elev-3), var(--focus-ring);
}

.island-stage > section {
  border-radius: calc(var(--island-stage-radius) - var(--island-stage-pad));
}

@keyframes island-stage-open {
  from {
    opacity: 0;
    transform: scale(0.94, 0.72);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.island-stage__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 42px;
  padding: 7px 10px 9px;
}

.island-stage__identity {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.island-stage__identity strong {
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font: 600 13px/1.25 var(--font);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.island-stage__eyebrow,
.island-stage__hint,
.island-agent__position {
  color: var(--fg-3);
  font: 600 9px/1.2 var(--font);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.island-stage__routes {
  display: flex;
  align-items: center;
  gap: 2px;
}

.island-stage__routes button,
.island-agent__stepper button {
  appearance: none;
  min-height: var(--ctl-h-sm);
  padding: 0 8px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--fg-3);
  font: 500 10px/1 var(--font);
  cursor: pointer;
}

.island-stage__routes button:hover,
.island-agent__stepper button:hover {
  background: var(--bg-hover);
  color: var(--fg);
}

.island-stage__routes button:focus-visible,
.island-agent__stepper button:focus-visible,
.island-agent__composer input:focus-visible,
.island-agent__composer button:focus-visible,
.island-agent__actions button:focus-visible,
.island-recall__input:focus-visible,
.island-recall__result:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.island-agent,
.island-sessions,
.island-recall {
  min-height: 0;
  background: var(--bg-raised);
  overflow: hidden;
}

.island-agent__idle {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 2px 4px 6px;
  padding: 12px;
  border-radius: calc(var(--island-stage-radius) - var(--island-stage-pad) - 4px);
  background: var(--bg-elevated);
}

.island-agent__pulse {
  width: 9px;
  height: 9px;
  flex: 0 0 9px;
  border-radius: var(--radius-pill);
  background: var(--ok);
  box-shadow: 0 0 0 5px var(--ok-soft);
}

.island-agent__idle strong,
.island-agent__idle p {
  display: block;
  margin: 0;
}

.island-agent__idle strong {
  color: var(--fg);
  font: 600 12px/1.4 var(--font);
}

.island-agent__idle p {
  margin-top: 2px;
  color: var(--fg-3);
  font: 400 10px/1.35 var(--font);
}

.island-agent__composer {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 6px;
  padding: 4px;
  border-radius: calc(var(--island-stage-radius) - var(--island-stage-pad));
  background: var(--bg-elevated);
  box-shadow: var(--well);
}

.island-agent__composer input {
  min-width: 0;
  min-height: 36px;
  padding: 0 10px;
  border: 0;
  border-radius: calc(var(--island-stage-radius) - var(--island-stage-pad) - 4px);
  outline: none;
  background: transparent;
  color: var(--fg);
  font: 400 12px/1.4 var(--font);
}

.island-agent__composer button,
.island-agent__actions button {
  appearance: none;
  min-height: var(--ctl-h-sm);
  padding: 0 10px;
  border: 0;
  border-radius: var(--radius);
  font: 600 10px/1 var(--font);
  cursor: pointer;
}

.island-agent__composer button,
.island-agent__approve {
  background: var(--accent);
  color: var(--fg-on-accent);
}

.island-agent__composer button:disabled,
.island-agent__actions button:disabled {
  opacity: 0.45;
  pointer-events: none;
}

.island-agent__position {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 28px;
  padding: 0 10px;
}

.island-agent__stepper {
  display: flex;
  align-items: center;
  gap: 2px;
}

.island-agent__work {
  margin: 0 4px 4px;
  padding: 12px;
  border-radius: calc(var(--island-stage-radius) - var(--island-stage-pad) - 4px);
  background: var(--bg-elevated);
}

.island-agent__work-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.island-agent__work-head strong {
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font: 600 12px/1.3 var(--font);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.island-agent__state {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--fg-3);
  font: 600 10px/1.3 var(--font);
}

.island-agent__state i {
  width: 7px;
  height: 7px;
  border-radius: var(--radius-pill);
  background: currentColor;
}

.island-agent__work.is-needs-human .island-agent__state,
.island-agent__work.is-cancelling .island-agent__state {
  color: var(--warn);
}

.island-agent__work.is-running .island-agent__state {
  color: var(--accent);
}

.island-agent__work.is-failed .island-agent__state {
  color: var(--err);
}

.island-agent__detail {
  margin: 10px 0 7px;
  color: var(--fg-2);
  font: 400 12px/1.5 var(--font);
  overflow-wrap: anywhere;
}

.island-agent__meta,
.island-recall__meta {
  display: flex;
  min-width: 0;
  overflow: hidden;
  color: var(--fg-3);
  font: 400 9px/1.4 var(--font);
  white-space: nowrap;
}

.island-agent__meta > span,
.island-recall__meta > span {
  min-width: 0;
  max-width: 24ch;
  overflow: hidden;
  text-overflow: ellipsis;
}

.island-agent__meta > span:empty,
.island-recall__meta > span:empty {
  display: none;
}

.island-agent__meta > span:not(:empty) ~ span:not(:empty)::before,
.island-recall__meta > span:not(:empty) ~ span:not(:empty)::before {
  content: "·";
  padding: 0 5px;
  color: var(--fg-4);
}

.island-agent__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  margin-top: 10px;
}

.island-agent__open {
  margin-right: auto;
  background: transparent;
  color: var(--fg-2);
}

.island-agent__open:hover {
  background: var(--bg-hover);
  color: var(--fg);
}

.island-agent__stop,
.island-agent__deny {
  background: transparent;
  color: var(--err);
}

.island-agent__stop:hover,
.island-agent__deny:hover {
  background: var(--err-soft);
}

.island-sessions .island-search,
.island-recall__search {
  margin: 0 4px 4px;
}

.island-sessions .island-results {
  max-height: min(370px, calc(100vh - 132px));
}

.island-recall__search {
  border-radius: var(--radius);
  background: var(--bg-elevated);
  box-shadow: var(--well);
}

.island-recall__input {
  appearance: none;
  display: block;
  width: 100%;
  min-height: 42px;
  padding: 10px 12px;
  border: 0;
  border-radius: var(--radius);
  outline: 0;
  background: transparent;
  color: var(--fg);
  caret-color: var(--accent);
  font: 400 13px/1.4 var(--font);
}

.island-recall__results {
  max-height: min(360px, calc(100vh - 132px));
  overflow-y: auto;
  padding: 2px 4px 4px;
}

.island-recall__prompt,
.island-recall__error {
  padding: 28px 14px;
  color: var(--fg-3);
  font: 400 11px/1.5 var(--font);
  text-align: center;
}

.island-recall__error {
  color: var(--err);
}

.island-recall__result {
  appearance: none;
  display: block;
  width: 100%;
  padding: 10px 12px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--fg-2);
  text-align: left;
  cursor: pointer;
}

.island-recall__result:hover,
.island-recall__result--selected {
  background: var(--bg-hover);
}

.island-recall__excerpt {
  display: -webkit-box;
  overflow: hidden;
  color: var(--fg);
  font: 500 12px/1.45 var(--font);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.island-recall__meta {
  margin-top: 5px;
}

@media (min-width: 900px) {
  .has-workspace-open .island-stage {
    right: calc(var(--workspace-w) + 16px);
    width: min(520px, calc(100vw - var(--workspace-w) - 32px));
  }

  .has-workspace-open .island-stage--agent {
    width: min(460px, calc(100vw - var(--workspace-w) - 32px));
  }

  .has-workspace-open .island-stage--recall {
    width: min(620px, calc(100vw - var(--workspace-w) - 32px));
  }
}

@media (max-width: 720px) {
  .island-stage {
    left: 10px;
    right: 10px;
    width: calc(100vw - 20px);
    max-height: min(520px, calc(100vh - 18px));
  }

  .island-stage__header {
    padding-inline: 8px;
  }

  .island-stage__routes {
    gap: 0;
  }

  .island-stage__routes button {
    padding-inline: 6px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .island-chip,
  .island-result,
  .island-stage {
    animation: none;
    transition: none;
  }
}

