+#[cfg(target_arch = "wasm32")]
+fn close_event_source(slot: &EventSourceSlot) {
+    let previous = slot.lock().expect("event source slot poisoned").take();
+    if let Some(previous) = previous {
+        previous.take().close();
+    }
+}
