637	                </span>
638	                <Show when=move || focused_session.get().and_then(|item| item.project).is_some()>
639	                    <span class="island-chip__separator" aria-hidden="true">"·"</span>
640	                    <span class="island-chip__project">
641	                        {move || focused_session.get().and_then(|item| item.project).unwrap_or_default()}
642	                    </span>
643	                </Show>
644	                <span class="island-chip__separator" aria-hidden="true">"·"</span>
645	                <span class="island-chip__count">{move || chip_status()}</span>
646	            </button>
647	            <span class="island-live" aria-live="polite" aria-atomic="true">
648	                {move || chip_status()}
649	            </span>
650	
651	            <Show when=move || mode.get() != IslandMode::Closed>
652	                <div class="island-dismiss-layer" aria-hidden="true" on:click=move |_| close.run(())></div>
653	                <section
654	                    id="island-stage"
655	                    class=move || format!(
656	                        "island-stage island-stage--{}",
657	                        match mode.get() {
658	                            IslandMode::Agent => "agent",
659	                            IslandMode::Sessions => "sessions",
660	                            IslandMode::Recall => "recall",
661	                            IslandMode::Closed => "closed",
662	                        }
663	                    )
664	                    node_ref=stage_ref
665	                    tabindex="-1"
666	                    role="dialog"
667	                    aria-modal="false"
668	                    aria-label=stage_label
669	                >
670	                    <Show when=move || mode.get() == IslandMode::Agent>
671	                        <AgentStage
672	                            daemon=daemon_value.get_value()
673	                            items=attention_items
674	                            selected_index=agent_selected
675	                            on_close=close
676	                            on_mode=switch_mode
677	                        />
678	                    </Show>
679	
680	                    <Show when=move || mode.get() == IslandMode::Sessions>
681	                        <section class="island-sessions" aria-label="Sessions">
682	                            <header class="island-stage__header">
683	                                <div class="island-stage__identity">
684	                                    <span class="island-stage__eyebrow">"Sessions"</span>
685	                                    <strong>"Switch focus"</strong>
686	                                </div>
687	                                <span class="island-stage__hint">"⌘P"</span>
688	                            </header>
689	                            <div class="island-search">
690	                                <input
691	                                    class="island-search__input"
692	                                    type="search"
693	                                    role="combobox"
694	                                    aria-label="Search sessions"
695	                                    aria-autocomplete="list"
696	                                    aria-expanded="true"
697	                                    aria-controls="island-session-results"
698	                                    aria-activedescendant=move || {
699	                                        let id = selected_session_id();
700	                                        (!id.is_empty()).then_some(id)
701	                                    }
702	                                    placeholder="Session, project, path, branch…"
703	                                    autocomplete="off"
704	                                    node_ref=session_input_ref
705	                                    prop:value=move || session_query.get()
706	                                    on:input=move |event| {
707	                                        session_query.set(event_target_value(&event));
708	                                        session_selected.set(0);
709	                                    }
710	                                />
711	                            </div>
712	                            <div id="island-session-results" class="island-results" role="listbox">
713	                                <Show
714	                                    when=move || !session_results.get().is_empty()
715	                                    fallback=|| view! { <div class="island-empty">"No matching sessions"</div> }
716	                                >
717	                                    <For
718	                                        each=move || session_results.get()
719	                                        key=|result| match result { IslandResult::Session(item) => item.id.clone() }
720	                                        children=move |result| {
721	                                            let IslandResult::Session(item) = result;
722	                                            let row_id = option_id("island-session", &item.id);
723	                                            let selected_id = row_id.clone();
724	                                            let aria_id = row_id.clone();
725	                                            let switch_id = item.id.clone();
726	                                            let switch_title = item.title.clone();
727	                                            let title = item.title.clone();
728	                                            let project = item.project.clone().unwrap_or_default();
729	                                            let cwd = item.cwd.clone();
730	                                            let branch = item.branch.clone().unwrap_or_default();
731	                                            let updated = fmt_relative_time(&item.updated_at);
732	                                            let is_focused = item.is_focused;
733	                                            view! {
734	                                                <button
735	                                                    id=row_id
736	                                                    class="island-result"
737	                                                    class:island-result--selected=move || selected_session_id() == selected_id
738	                                                    class:island-result--focused=is_focused
739	                                                    type="button"
740	                                                    role="option"
741	                                                    tabindex="-1"
742	                                                    aria-selected=move || (selected_session_id() == aria_id).to_string()
743	                                                    on:click=move |_| {
744	                                                        daemon_value.get_value().switch_session(
745	                                                            switch_id.clone(),
746	                                                            switch_title.clone(),
747	                                                        );
748	                                                        close.run(());
749	                                                    }
750	                                                >
751	                                                    <span class="island-result__primary">
752	                                                        <span class="island-result__title">{title}</span>
753	                                                        <Show when=move || is_focused>
754	                                                            <span class="island-result__focused">"Focused"</span>
755	                                                        </Show>
756	                                                    </span>
757	                                                    <span class="island-result__meta">
758	                                                        <span>{project}</span>
759	                                                        <span class="island-result__path">{cwd}</span>
760	                                                        <span>{branch}</span>

