  1	//! Dynamic, mode-separated Tauri titlebar Island.
  2	//!
  3	//! The compact object opens focused-agent interaction. Session switching and
  4	//! transcript recall are distinct surfaces with distinct entry points and
  5	//! result semantics; they are never stacked into one dashboard.
  6	
  7	use leptos::ev::{KeyboardEvent, SubmitEvent};
  8	use leptos::prelude::*;
  9	use wasm_bindgen::JsCast;
 10	
 11	use crate::daemon::{Daemon, HistorySearchHit};
 12	use crate::island::{
 13	    compact_attention_counts, derive_attention_items, derive_island_sessions,
 14	    permission_action_state, search_island, stop_action_state, IslandAttentionItem, IslandResult,
 15	};
 16	use crate::sessions::fmt_relative_time;
 17	
 18	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
 19	pub enum IslandMode {
 20	    Closed,
 21	    Agent,
 22	    Sessions,
 23	    Recall,
 24	}
 25	
 26	fn option_id(prefix: &str, value: &str) -> String {
 27	    let encoded = value
 28	        .as_bytes()
 29	        .iter()
 30	        .map(|byte| format!("{byte:02x}"))
 31	        .collect::<String>();
 32	    format!("{prefix}-{encoded}")
 33	}
 34	
 35	fn next_index(index: usize, len: usize) -> usize {
 36	    if len == 0 {
 37	        0
 38	    } else {
 39	        (index + 1) % len
 40	    }
 41	}
 42	
 43	fn previous_index(index: usize, len: usize) -> usize {
 44	    if len == 0 {
 45	        0
 46	    } else {
 47	        (index + len - 1) % len
 48	    }
 49	}
 50	
 51	fn history_result_label(hit: &HistorySearchHit) -> String {
 52	    let title = if hit.session_title.trim().is_empty() {
 53	        "Untitled session"
 54	    } else {
 55	        hit.session_title.trim()
 56	    };
 57	    format!("Open history match from {title}")
 58	}
