 60	#[component]
 61	fn AgentStage(
 62	    daemon: Daemon,
 63	    items: Memo<Vec<IslandAttentionItem>>,
 64	    selected_index: RwSignal<usize>,
 65	    on_close: Callback<()>,
 66	    on_mode: Callback<IslandMode>,
 67	) -> impl IntoView {
 68	    let prompt = RwSignal::new(String::new());
 69	    let prompt_ref: NodeRef<leptos::html::Input> = NodeRef::new();
 70	    let focused_id = daemon.session_id;
 71	    let pending_permissions = daemon.pending_permissions;
 72	    let active_decision_token = daemon.active_decision_token;
 73	    let request_cancellations = daemon.request_cancellations;
 74	    let session_title = daemon.session_title;
 75	    let status = daemon.status;
 76	    let daemon = StoredValue::new(daemon);
 77	
 78	    Effect::new(move |_| {
 79	        let len = items.get().len();
 80	        if len == 0 {
 81	            selected_index.set(0);
 82	            request_animation_frame(move || {
 83	                if let Some(input) = prompt_ref.get() {
 84	                    let _ = input.focus();
 85	                }
 86	            });
 87	        } else if selected_index.get() >= len {
 88	            selected_index.set(0);
 89	        }
 90	    });
 91	
 92	    let submit = move |event: SubmitEvent| {
 93	        event.prevent_default();
 94	        let text = prompt.get_untracked().trim().to_string();
 95	        if text.is_empty() {
 96	            return;
 97	        }
 98	        daemon.get_value().send_prompt(text);
 99	        prompt.set(String::new());
100	        on_close.run(());
101	    };
102	
103	    view! {
104	        <section class="island-agent" aria-label="Agent interaction">
105	            <header class="island-stage__header">
106	                <div class="island-stage__identity">
107	                    <span class="island-stage__eyebrow">"Agent"</span>
108	                    <strong>{move || {
109	                        let title = session_title.get();
110	                        if title.trim().is_empty() { "Ocean".to_string() } else { title }
111	                    }}</strong>
112	                </div>
113	                <div class="island-stage__routes" aria-label="Island tools">
114	                    <button type="button" on:click=move |_| on_mode.run(IslandMode::Sessions)>
115	                        "Sessions"
116	                    </button>
117	                    <button type="button" on:click=move |_| on_mode.run(IslandMode::Recall)>
118	                        "Recall"
119	                    </button>
120	                </div>
121	            </header>
122	
123	            <Show when=move || items.get().is_empty()>
124	                <div class="island-agent__idle">
125	                    <span class="island-agent__pulse" aria-hidden="true"></span>
126	                    <div>
127	                        <strong>"Ocean is ready"</strong>
128	                        <p>{move || status.get()}</p>
129	                    </div>
130	                </div>
131	                <form class="island-agent__composer" on:submit=submit>
132	                    <input
133	                        node_ref=prompt_ref
134	                        type="text"
135	                        aria-label="Ask Ocean in the focused session"
136	                        placeholder="Ask Ocean…"
137	                        autocomplete="off"
138	                        prop:value=move || prompt.get()
139	                        on:input=move |event| prompt.set(event_target_value(&event))
140	                    />
141	                    <button type="submit" disabled=move || prompt.get().trim().is_empty()>
142	                        "Send"
143	                    </button>
144	                </form>
145	            </Show>
146	
147	            <Show when=move || !items.get().is_empty()>
148	                <div class="island-agent__position">
149	                    <span>{move || {
150	                        let len = items.get().len();
151	                        format!("Work {} of {len}", selected_index.get().min(len.saturating_sub(1)) + 1)
152	                    }}</span>
153	                    <Show when=move || items.get().len().ge(&2)>
154	                        <div class="island-agent__stepper">
155	                            <button
156	                                type="button"
157	                                aria-label="Previous agent work item"
158	                                on:click=move |_| {
159	                                    let len = items.get_untracked().len();
160	                                    selected_index.update(|index| *index = previous_index(*index, len));
161	                                }
162	                            >"←"</button>
163	                            <button
164	                                type="button"
165	                                aria-label="Next agent work item"
166	                                on:click=move |_| {
167	                                    let len = items.get_untracked().len();
168	                                    selected_index.update(|index| *index = next_index(*index, len));
169	                                }
170	                            >"→"</button>
171	                        </div>
172	                    </Show>
173	                </div>
174	
175	                <For
176	                    each=move || {
177	                        items
178	                            .get()
179	                            .get(selected_index.get())
180	                            .cloned()
181	                            .into_iter()
182	                            .collect::<Vec<_>>()
183	                    }
184	                    key=|item| (item.id.clone(), item.state, item.updated_at.clone())
185	                    children=move |item| {
186	                        let item_class = format!(
187	                            "island-agent__work {}",
188	                            item.state.class_name(),
189	                        );
190	                        let state_label = item.state.label();
191	                        let session_name = item.session_title.clone();
192	                        let detail = item.detail.clone();
193	                        let project = item.project.clone().unwrap_or_default();
194	                        let tool = item.tool.clone().unwrap_or_default();
195	                        let updated = if item.updated_at.is_empty() {
196	                            String::new()
197	                        } else {
198	                            fmt_relative_time(&item.updated_at)
199	                        };
200	                        let permission_id = StoredValue::new_local(item.permission_id.clone());
201	                        let permission_session = StoredValue::new_local(item.session_id.clone());
202	                        let open_target = StoredValue::new_local((
203	                            item.session_id.clone(),
204	                            item.session_title.clone(),
205	                        ));
206	                        let request_id = StoredValue::new_local(item.request_id.clone());
207	                        let item_state = item.state;
208	                        let permission_action = Memo::new(move |_| {
209	                            permission_action_state(
210	                                permission_id.get_value().as_deref(),
211	                                permission_session.get_value().as_deref(),
212	                                focused_id.get().as_deref(),
213	                                active_decision_token.get().is_some(),
214	                                &pending_permissions.get(),
215	                            )
216	                        });
217	                        let stop_action = Memo::new(move |_| {
218	                            stop_action_state(
219	                                item_state,
220	                                &request_id.get_value(),
221	                                &request_cancellations.get(),
222	                            )
223	                        });
224	                        let open_action = Memo::new(move |_| {
225	                            let (session_id, _) = open_target.get_value();
226	                            permission_action.get().is_none()
227	                                && session_id.is_some()
228	                                && session_id.as_deref() != focused_id.get().as_deref()
229	                        });
230	
231	                        view! {
232	                            <article class=item_class>
233	                                <div class="island-agent__work-head">
234	                                    <span class="island-agent__state">
235	                                        <i aria-hidden="true"></i>
236	                                        {state_label}
237	                                    </span>
238	                                    <strong>{session_name}</strong>
239	                                </div>
240	                                <p class="island-agent__detail">{detail}</p>
241	                                <div class="island-agent__meta">
242	                                    <span>{project}</span>
243	                                    <span>{tool}</span>
244	                                    <span>{updated}</span>
245	                                </div>
246	                                <div class="island-agent__actions">
247	                                    <Show when=move || open_action.get()>
248	                                        <button
249	                                            class="island-agent__open"
250	                                            type="button"
251	                                            on:click=move |_| {
252	                                                let (session_id, title) = open_target.get_value();
253	                                                if let Some(session_id) = session_id {
254	                                                    daemon.get_value().switch_session(session_id, title);
255	                                                    on_close.run(());
256	                                                }
257	                                            }
258	                                        >"Open session"</button>
259	                                    </Show>
260	                                    <Show when=move || stop_action.get().is_some()>
261	                                        <button
262	                                            class="island-agent__stop"
263	                                            type="button"
264	                                            disabled=move || stop_action.get().unwrap_or(true)
265	                                            on:click=move |_| {
266	                                                daemon.get_value().cancel_request(request_id.get_value());
267	                                            }
268	                                        >
269	                                            {move || if stop_action.get() == Some(true) { "Stopping…" } else { "Stop" }}
270	                                        </button>
271	                                    </Show>
272	                                    <Show when=move || permission_action.get().is_some()>
273	                                        <button
274	                                            class="island-agent__deny"
275	                                            type="button"
276	                                            disabled=move || permission_action.get().unwrap_or(true)
277	                                            on:click=move |_| {
278	                                                if let Some(permission_id) = permission_id.get_value() {
279	                                                    daemon.get_value().decide_permission(permission_id, false);
280	                                                }
281	                                            }
282	                                        >"Deny"</button>
283	                                        <button
284	                                            class="island-agent__approve"
285	                                            type="button"
286	                                            disabled=move || permission_action.get().unwrap_or(true)
287	                                            on:click=move |_| {
288	                                                if let Some(permission_id) = permission_id.get_value() {
289	                                                    daemon.get_value().decide_permission(permission_id, true);
290	                                                }
291	                                            }
292	                                        >
293	                                            {move || if permission_action.get() == Some(true) { "Working…" } else { "Approve" }}
294	                                        </button>
295	                                    </Show>
296	                                </div>
297	                            </article>
298	                        }
299	                    }
300	                />
301	            </Show>
302	        </section>
303	    }
304	}
