306	#[component]
307	pub fn DynamicIsland(
308	    daemon: Daemon,
309	    mode: RwSignal<IslandMode>,
310	    focus_request: RwSignal<u64>,
311	    on_open: Callback<IslandMode>,
312	) -> impl IntoView {
313	    let session_query = RwSignal::new(String::new());
314	    let history_query = RwSignal::new(String::new());
315	    let session_selected = RwSignal::new(0usize);
316	    let history_selected = RwSignal::new(0usize);
317	    let agent_selected = RwSignal::new(0usize);
318	    let history_debounce = RwSignal::new(0u64);
319	    let previous_mode = RwSignal::new(IslandMode::Closed);
320	    let previous_focus = StoredValue::new_local(None::<web_sys::HtmlElement>);
321	    let last_focus_request = RwSignal::new(0u64);
322	    let session_input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
323	    let history_input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
324	    let chip_ref: NodeRef<leptos::html::Button> = NodeRef::new();
325	    let stage_ref: NodeRef<leptos::html::Section> = NodeRef::new();
326	
327	    #[cfg(target_arch = "wasm32")]
328	    let attention_interval = {
329	        let daemon = daemon.clone();
330	        send_wrapper::SendWrapper::new(gloo_timers::callback::Interval::new(3_000, move || {
331	            daemon.fetch_attention();
332	        }))
333	    };
334	    #[cfg(target_arch = "wasm32")]
335	    on_cleanup(move || drop(attention_interval));
336	
337	    let session_list = daemon.session_list;
338	    let request_list = daemon.request_list;
339	    let permission_list = daemon.permission_list;
340	    let projects = daemon.projects;
341	    let focused_id = daemon.session_id;
342	    let history_results = daemon.history_results;
343	    let history_searching = daemon.history_searching;
344	    let history_error = daemon.history_error;
345	    let daemon_value = StoredValue::new(daemon.clone());
346	
347	    daemon.fetch_sessions();
348	    daemon.fetch_projects();
349	    daemon.fetch_attention();
350	
351	    let sessions = Memo::new(move |_| {
352	        derive_island_sessions(
353	            &session_list.get(),
354	            &projects.get(),
355	            focused_id.get().as_deref(),
356	        )
357	    });
358	    let attention_items = Memo::new(move |_| {
359	        derive_attention_items(&request_list.get(), &permission_list.get(), &sessions.get())
360	    });
361	    let attention_counts = Memo::new(move |_| compact_attention_counts(&attention_items.get()));
362	    let session_results = Memo::new(move |_| {
363	        let mut matches = search_island(&session_query.get(), &sessions.get());
364	        matches.truncate(if session_query.get().trim().is_empty() {
365	            8
366	        } else {
367	            20
368	        });
369	        matches
370	    });
371	
372	    Effect::new(move |_| {
373	        let len = session_results.get().len();
374	        if len == 0 || session_selected.get() >= len {
375	            session_selected.set(0);
376	        }
377	    });
378	    Effect::new(move |_| {
379	        let len = history_results.get().len();
380	        if len == 0 || history_selected.get() >= len {
381	            history_selected.set(0);
382	        }
383	    });
384	
385	    Effect::new(move |_| {
386	        let next = mode.get();
387	        let request = focus_request.get();
388	        let previous = previous_mode.get_untracked();
389	        let previous_request = last_focus_request.get_untracked();
390	        if next != IslandMode::Closed && previous == IslandMode::Closed {
391	            previous_focus.set_value(
392	                web_sys::window()
393	                    .and_then(|window| window.document())
394	                    .and_then(|document| document.active_element())
395	                    .and_then(|element| element.dyn_into::<web_sys::HtmlElement>().ok()),
396	            );
397	            let daemon = daemon_value.get_value();
398	            daemon.fetch_sessions();
399	            daemon.fetch_projects();
400	            daemon.fetch_attention();
401	        }
402	        let should_focus = next != IslandMode::Closed
403	            && (previous == IslandMode::Closed || next != previous || request != previous_request);
404	        if should_focus {
405	            request_animation_frame(move || match next {
406	                IslandMode::Sessions => {
407	                    if let Some(input) = session_input_ref.get() {
408	                        let _ = input.focus();
409	                        input.select();
410	                    }
411	                }
412	                IslandMode::Recall => {
413	                    if let Some(input) = history_input_ref.get() {
414	                        let _ = input.focus();
415	                        input.select();
416	                    }
417	                }
418	                IslandMode::Agent => {
419	                    if let Some(stage) = stage_ref.get() {
420	                        let _ = stage.focus();
421	                    }
422	                }
423	                IslandMode::Closed => {}
424	            });
425	        } else if next == IslandMode::Closed && previous != IslandMode::Closed {
426	            request_animation_frame(move || {
427	                if let Some(element) = previous_focus.get_value().filter(|el| el.is_connected()) {
428	                    let _ = element.focus();
429	                } else if let Some(chip) = chip_ref.get() {
430	                    let _ = chip.focus();
431	                }
432	            });
433	        }
434	        previous_mode.set(next);
435	        last_focus_request.set(request);
436	    });
437	
438	    let close = Callback::new(move |()| mode.set(IslandMode::Closed));
439	    let switch_mode = Callback::new(move |next| on_open.run(next));
440	    let selected_session_id = move || {
441	        session_results
442	            .get()
443	            .get(session_selected.get())
444	            .map(|result| match result {
445	                IslandResult::Session(item) => option_id("island-session", &item.id),
446	            })
447	            .unwrap_or_default()
448	    };
449	    let selected_history_id = move || {
450	        history_results
451	            .get()
452	            .get(history_selected.get())
453	            .map(|hit| option_id("island-history", &hit.hit_id))
454	            .unwrap_or_default()
455	    };
456	
457	    let on_keydown = move |event: KeyboardEvent| {
458	        if event.is_composing() || mode.get_untracked() == IslandMode::Closed {
459	            return;
460	        }
461	        if event.key() == "Escape" {
462	            event.prevent_default();
463	            event.stop_propagation();
464	            close.run(());
465	            return;
466	        }
