2691	        let base = self.url.get_untracked().trim_end_matches('/').to_string();
2692	        let request_list = self.request_list;
2693	        let permission_list = self.permission_list;
2694	        let attention_fetching = self.attention_fetching;
2695	        let request_cancellations = self.request_cancellations;
2696	        spawn_local(async move {
2697	            #[derive(Deserialize)]
2698	            struct RequestsResponse {
2699	                ok: bool,
2700	                #[serde(default)]
2701	                requests: Vec<RequestSnapshot>,
2702	            }
2703	            #[derive(Deserialize)]
2704	            struct PermissionsResponse {
2705	                ok: bool,
2706	                #[serde(default)]
2707	                permissions: Vec<PermissionSnapshot>,
2708	            }
2709	
2710	            let (requests_response, permissions_response) = futures_util::join!(
2711	                Request::get(&format!("{base}/v1/requests")).send(),
2712	                Request::get(&format!("{base}/v1/permissions")).send(),
2713	            );
2714	
2715	            match requests_response {
2716	                Ok(resp) => match resp.json::<RequestsResponse>().await {
2717	                    Ok(snapshot) if snapshot.ok => {
2718	                        request_cancellations.update(|pending| {
2719	                            pending.retain(|request_id| {
2720	                                snapshot.requests.iter().any(|request| {
2721	                                    request.request_id == *request_id
2722	                                        && matches!(
2723	                                            request.state,
2724	                                            RequestSnapshotState::Queued
2725	                                                | RequestSnapshotState::Running
2726	                                        )
2727	                                })
2728	                            })
2729	                        });
2730	                        request_list.set(snapshot.requests);
2731	                    }
2732	                    Ok(_) => log::warn!("attention requests fetch not ok"),
2733	                    Err(err) => log::warn!("attention requests decode error: {err}"),
2734	                },
2735	                Err(err) => log::warn!("attention requests fetch error: {err}"),
2736	            }
2737	
2738	            match permissions_response {
2739	                Ok(resp) => match resp.json::<PermissionsResponse>().await {
2740	                    Ok(snapshot) if snapshot.ok => permission_list.set(snapshot.permissions),
2741	                    Ok(_) => log::warn!("attention permissions fetch not ok"),
2742	                    Err(err) => log::warn!("attention permissions decode error: {err}"),
2743	                },
2744	                Err(err) => log::warn!("attention permissions fetch error: {err}"),
2745	            }
2746	            attention_fetching.set(false);
2747	        });
2748	    }
