2750	    /// Search persisted user/assistant transcript text through the daemon-owned
2751	    /// Recall endpoint. Empty queries clear the view locally. Generation checks
2752	    /// ensure an older, slower request can never replace newer results.
2753	    pub fn search_history(&self, query: String) {
2754	        let query = query.trim().to_string();
2755	        let generation = self
2756	            .history_search_generation
2757	            .get_untracked()
2758	            .wrapping_add(1);
2759	        self.history_search_generation.set(generation);
2760	        if query.is_empty() {
2761	            self.history_results.set(Vec::new());
2762	            self.history_error.set(None);
2763	            self.history_searching.set(false);
2764	            return;
2765	        }
2766	
2767	        self.history_searching.set(true);
2768	        self.history_error.set(None);
2769	        self.history_results.set(Vec::new());
2770	        let base = self.url.get_untracked().trim_end_matches('/').to_string();
2771	        let encoded = js_sys::encode_uri_component(&query)
2772	            .as_string()
2773	            .unwrap_or_else(|| query.clone());
2774	        let url = format!("{base}/v1/agent/history/search?q={encoded}&limit=20");
2775	        let active_generation = self.history_search_generation;
2776	        let history_results = self.history_results;
2777	        let history_searching = self.history_searching;
2778	        let history_error = self.history_error;
2779	        spawn_local(async move {
2780	            let result = match Request::get(&url).send().await {
2781	                Ok(response) => match response.json::<HistorySearchResponse>().await {
2782	                    Ok(payload) if payload.ok => Ok(payload.hits),
2783	                    Ok(payload) => Err(payload
2784	                        .error
2785	                        .filter(|error| !error.trim().is_empty())
2786	                        .unwrap_or_else(|| "History search failed".to_string())),
2787	                    Err(error) => Err(format!("History response was unreadable: {error}")),
2788	                },
2789	                Err(error) => Err(format!("History search is unavailable: {error}")),
2790	            };
2791	            if active_generation.get_untracked() != generation {
2792	                return;
2793	            }
2794	            match result {
2795	                Ok(hits) => {
2796	                    history_results.set(hits);
2797	                    history_error.set(None);
2798	                }
2799	                Err(error) => {
2800	                    history_results.set(Vec::new());
2801	                    history_error.set(Some(error));
2802	                }
2803	            }
2804	            history_searching.set(false);
2805	        });
2806	    }
