2809	    pub fn fetch_models(&self) {
2810	        let url = self.url.get_untracked();
2811	        let models = self.models;
2812	        let model = self.model;
2813	        spawn_local(async move {
2814	            #[derive(Deserialize)]
2815	            struct Current {
2816	                #[serde(default)]
2817	                model: String,
2818	            }
2819	            #[derive(Deserialize)]
2820	            struct ModelsResponse {
2821	                #[serde(default)]
2822	                models: Vec<ModelInfo>,
2823	                #[serde(default)]
2824	                current: Option<Current>,
2825	            }
2826	            let get_url = format!("{}/v1/models", url.trim_end_matches('/'));
2827	            match Request::get(&get_url).send().await {
2828	                Ok(resp) => match resp.json::<ModelsResponse>().await {
2829	                    Ok(r) => {
2830	                        if let Some(cur) = r.current {
2831	                            if !cur.model.is_empty() {
2832	                                model.set(Some(cur.model));
2833	                            }
2834	                        }
2835	                        models.set(r.models);
2940	            match Request::post(&post_url)
2941	                .header("content-type", "application/json")
2942	                .json(&body)
2943	            {
2944	                Ok(req) => match req.send().await {
2945	                    Ok(_) => {
2946	                        // Confirm the authoritative selection.
2947	                        daemon.fetch_models();
2948	                    }
2949	                    Err(err) => {
2950	                        let raw = err.to_string();
2951	                        log::error!("model swap error: {raw}");
2952	                        status.set(format!("model swap error: {}", concise_error(&raw)));
2953	                    }
2954	                },
2955	                Err(err) => {
2956	                    let raw = err.to_string();
2957	                    log::error!("model encode error: {raw}");
2958	                    status.set(format!("model encode error: {}", concise_error(&raw)));
2959	                }
2960	            }
2961	        });
2962	    }
