2964	    /// Halt the focused in-flight turn, if any. The composer and Island share
2965	    /// the same explicit request-cancel path so their status/error behavior
2966	    /// cannot drift.
2967	    pub fn halt(&self) {
2968	        let Some(turn_id) = self.active_turn_id.get_untracked() else {
2969	            return;
2970	        };
2971	        self.cancel_request(turn_id);
2972	    }
2973	
2974	    /// Request cancellation for any daemon-owned running request. This is the
2975	    /// mutation seam used by Phase 3B Island cards; the daemon remains the
2976	    /// lifecycle authority, while `request_cancellations` tracks only the POST
2977	    /// in flight so the action cannot be double-submitted.
2978	    pub fn cancel_request(&self, request_id: String) {
2979	        if self
2980	            .request_cancellations
2981	            .with_untracked(|requests| requests.iter().any(|id| id == &request_id))
2982	        {
2983	            return;
2984	        }
2985	        self.request_cancellations
2986	            .update(|requests| requests.push(request_id.clone()));
2987	
2988	        let url = self.url.get_untracked();
2989	        let status = self.status;
2990	        let status_detail = self.status_detail;
2991	        let streaming = self.streaming;
2992	        let active_turn_id = self.active_turn_id;
2993	        let request_cancellations = self.request_cancellations;
2994	        let daemon = self.clone();
2995	        spawn_local(async move {
2996	            let post_url = format!(
2997	                "{}/v1/requests/{request_id}/cancel",
2998	                url.trim_end_matches('/')
2999	            );
3000	            let mut accepted = false;
3001	            match Request::post(&post_url).send().await {
3002	                Ok(response) => {
3003	                    let http_ok = response.ok();
3004	                    let raw = response.text().await.unwrap_or_default();
3005	                    match request_cancel_result(http_ok, &raw) {
3006	                        Ok(()) => {
3007	                            accepted = true;
3008	                            if active_turn_id.get_untracked().as_deref()
3009	                                == Some(request_id.as_str())
3010	                            {
3011	                                status.set("halting…".into());
3012	                                status_detail.set(None);
3013	                                // The terminal SSE frame remains authoritative;
3014	                                // release the focused composer's Stop state once
3015	                                // the daemon accepted cancellation.
3016	                                streaming.set(false);
3017	                            }
3018	                            daemon.fetch_attention();
3019	                        }
3020	                        Err(message) => {
3021	                            let concise = format!("stop failed: {}", concise_error(&message));
3022	                            log::error!("request cancellation failed: {raw}");
3023	                            status.set(concise.clone());
3024	                            status_detail.set(Some((concise, raw)));
3025	                        }
3026	                    }
3027	                }
3028	                Err(err) => {
3029	                    let raw = err.to_string();
3030	                    let concise = format!("stop failed: {}", concise_error(&raw));
3031	                    log::error!("request cancellation error: {raw}");
3032	                    status.set(concise.clone());
3033	                    status_detail.set(Some((concise, raw)));
3034	                }
3035	            }
3036	            if !accepted {
3037	                request_cancellations.update(|requests| requests.retain(|id| id != &request_id));
3038	            }
3039	        });
3040	    }
