content.text:
  1	/* Dynamic Island — native agent interaction, Sessions, and Recall. Tauri-only
  2	   in the component tree; these selectors remain inert on web/extension hosts. */
  3	
  4	:root {
  5	  --island-max-w: 520px;
  6	  --island-top: 64px;
  7	}
  8	
  9	.ocean-header {
 10	  position: relative;
 11	}
 12	
 13	.ocean-header__left {
 14	  display: flex;
 15	  align-items: center;
 16	  min-width: 0;
 17	}
 18	
 19	/* Center inside the real header/content column without transform. Fixed
 20	   descendants therefore stay viewport-fixed instead of inheriting a new
 21	   containing block. The percentage cap reserves both titlebar control zones. */
 22	.island-host {
 23	  position: absolute;
 24	  inset-inline: 0;
 25	  top: 11px;
 26	  width: min(var(--island-max-w), 44%);
 27	  height: var(--ctl-h);
 28	  margin-inline: auto;
 29	  z-index: 122;
 30	}
 31	
 32	.island-chip {
 33	  box-sizing: border-box;
 34	  position: relative;
 35	  z-index: 122;
 36	  display: flex;
 37	  align-items: center;
 38	  gap: 7px;
 39	  width: 100%;
 40	  max-width: 100%;
 41	  height: var(--ctl-h);
 42	  min-width: 0;
 43	  padding: 0 12px;
 44	  border: 0;
 45	  border-radius: var(--radius);
 46	  background: var(--bg-elevated);
 47	  box-shadow: var(--elev-1);
 48	  color: var(--fg);
 49	  font: 500 12px/1 var(--font);
 50	  cursor: pointer;
 51	  overflow: hidden;
 52	  transition: background var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
 53	}
 54	
 55	.island-chip:hover,
 56	.island-chip[aria-expanded="true"] {
 57	  background: var(--bg-hover);
 58	}
 59	
 60	.island-chip:focus-visible {
 61	  box-shadow: var(--elev-1), var(--focus-ring);
 62	}
 63	
 64	.island-chip__dot {
 65	  width: 7px;
 66	  height: 7px;
 67	  flex: 0 0 7px;
 68	  border-radius: var(--radius-pill);
 69	  background: var(--fg-3);
 70	}
 71	
 72	.island-chip__dot.is-empty {
 73	  background: var(--fg-4);
 74	}
 75	
 76	.island-chip.is-attention .island-chip__count {
 77	  color: var(--warn);
 78	}
 79	
 80	.island-chip__dot.is-attention {
 81	  background: var(--warn);
 82	}
 83	
 84	.island-chip.is-running .island-chip__count {
 85	  color: var(--accent);
 86	}
 87	
 88	.island-chip__dot.is-running {
 89	  background: var(--accent);
 90	}
 91	
 92	.island-live {
 93	  position: absolute;
 94	  width: 1px;
 95	  height: 1px;
 96	  padding: 0;
 97	  margin: -1px;
 98	  overflow: hidden;
 99	  clip: rect(0, 0, 0, 0);
100	  white-space: nowrap;
101	}
102	
103	.island-chip__title,
104	.island-chip__project,
105	.island-chip__count {
106	  min-width: 0;
107	  overflow: hidden;
108	  text-overflow: ellipsis;
109	  white-space: nowrap;
110	}
111	
112	.island-chip__title {
113	  flex: 1 1 auto;
114	  text-align: left;
115	}
116	
117	.island-chip__project {
118	  flex: 0 1 auto;
