120	}
121	
122	.island-chip__count,
123	.island-chip__separator {
124	  flex: 0 0 auto;
125	  color: var(--fg-2);
126	}
127	
128	.island-search {
129	  flex: 0 0 auto;
130	  border-radius: var(--radius);
131	  background: var(--bg-elevated);
