197	  align-items: center;
198	  min-width: 0;
199	}
200	
201	.island-result__primary {
202	  gap: 8px;
203	}
204	
205	.island-result__title {
206	  min-width: 0;
207	  overflow: hidden;
208	  text-overflow: ellipsis;
