222	  text-transform: uppercase;
223	}
224	
225	.island-result__meta {
226	  gap: 0;
227	  margin-top: 3px;
228	  color: var(--fg-3);
229	  font: 400 10px/1.4 var(--font);
230	  white-space: nowrap;
