262	/* The workspace becomes a split column at 900px and may consume up to 65%
263	   of the window. Keep the remaining header to the identity dot/state dots so
264	   the centered Island has stable reserved tracks even at that maximum. */
265	@media (min-width: 900px) {
266	  .has-workspace-open .ocean-brand__word,
267	  .has-workspace-open .ocean-tokens,
268	  .has-workspace-open .ocean-status__text,
269	  .has-workspace-open .ocean-browser-control__label {
270	    display: none;
271	  }
272	}
273	
274	@media (min-width: 900px) and (max-width: 1100px) {
275	  .has-workspace-open .ocean-brand {
276	    display: none;
277	  }
278	}
279	
280	@media (max-width: 1000px) {
281	  .island-host {
282	    width: min(300px, 42%);
283	  }
284	
285	  .island-chip__project,
286	  .island-chip__separator {
287	    display: none;
288	  }
289	}
290	
291	/* Below the split-view breakpoint the workspace overlays from the right.
292	   Center the chip in the still-visible transcript column so workspace tabs
293	   never paint through the titlebar control. The popover remains viewport-wide
294	   and above the workspace, preserving the compact overlay behavior. */
295	@media (max-width: 899px) {
296	  .has-workspace-open .island-host {
297	    right: var(--workspace-w);
298	    /* The workspace resizer may intentionally leave only a 48px context
299	       sliver. Collapse rather than painting through traffic lights or tabs
300	       when that sliver cannot safely hold the interactive titlebar control. */
301	    max-width: max(0px, calc(100vw - var(--workspace-w) - 160px));
302	  }
303	}
304	
305	@media (min-width: 721px) and (max-width: 840px) {
306	  .has-workspace-open .island-host {
307	    max-width: max(0px, calc(100vw - var(--workspace-w) - 220px));
308	  }
309	}
310	
311	@media (min-width: 841px) and (max-width: 899px) {
312	  .has-workspace-open .island-host {
313	    max-width: max(0px, calc(100vw - var(--workspace-w) - 300px));
314	  }
315	}
316	
317	@media (max-width: 840px) {
318	  .is-titlebar .ocean-brand__word {
319	    display: none;
320	  }
321	
322	  .island-host {
323	    width: min(240px, 38%);
324	  }
