332	@media (max-width: 720px) {
333	  /* compact.css is later in the cascade; this higher-specificity titlebar
334	     rule keeps the native traffic-light inset at the supported minimum. */
335	  main.ocean-surface.is-titlebar .ocean-header {
336	    padding-left: var(--titlebar-inset);
337	  }
338	
339	  .island-host {
340	    width: min(210px, 36%);
341	  }
342	
343	  .has-workspace-open .ocean-brand {
344	    display: none;
345	  }
