349	/* Dynamic Island v2 — one titlebar object, three mutually exclusive tools.
350	   The fixed outer stage begins behind the compact capsule so opening reads as
351	   the object changing shape, not a button spawning a detached modal. */
352	.island-dismiss-layer {
353	  position: fixed;
354	  inset: 0;
355	  z-index: 120;
356	  background: transparent;
357	}
358	
359	.island-stage {
360	  --island-stage-radius: 22px;
361	  --island-stage-pad: 6px;
362	  position: fixed;
363	  top: 8px;
364	  left: 16px;
